//! The writers against what Python wrote: `tests/fixtures/harness.json`,
//! regenerated by `python3 tools/pack_parity.py --write-fixtures` (and held
//! current by `tests/test_pack_parity.py`). Synthetic cases only.

use psiv_pack::json::{Json, dumps};
use psiv_pack::png::{encode_indexed, encode_rgb, image_sha256};
use serde_json::Value;

fn fixture() -> Value {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/fixtures/harness.json");
    serde_json::from_str(&std::fs::read_to_string(path).expect("the fixture")).expect("JSON")
}

/// `tools/pack_parity.py`'s `_tag` form back to a value.
fn untag(tagged: &Value) -> Json {
    let (kind, value) = tagged.as_object().unwrap().iter().next().unwrap();
    match kind.as_str() {
        "null" => Json::Null,
        "bool" => Json::Bool(value.as_bool().unwrap()),
        "int" => Json::Int(value.as_str().unwrap().parse().unwrap()),
        "float" => Json::Float(f64::from_bits(value.as_str().unwrap().parse().unwrap())),
        "str" => Json::Str(value.as_str().unwrap().to_owned()),
        "array" => Json::Array(value.as_array().unwrap().iter().map(untag).collect()),
        "object" => Json::Object(
            value
                .as_array()
                .unwrap()
                .iter()
                .map(|pair| (pair[0].as_str().unwrap().to_owned(), untag(&pair[1])))
                .collect(),
        ),
        other => panic!("unknown tag {other}"),
    }
}

fn base64(text: &str) -> Vec<u8> {
    const ALPHABET: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut out = Vec::new();
    let (mut acc, mut bits) = (0u32, 0);
    for c in text.bytes().filter(|&c| c != b'=') {
        let v = ALPHABET.iter().position(|&a| a == c).expect("base64") as u32;
        acc = (acc << 6) | v;
        bits += 6;
        if bits >= 8 {
            bits -= 8;
            out.push((acc >> bits) as u8);
        }
    }
    out
}

#[test]
fn json_matches_python_dumps() {
    let cases = fixture()["json"].as_array().unwrap().clone();
    assert!(cases.len() > 20, "the fixture has its cases");
    for case in &cases {
        let value = untag(&case["value"]);
        let sort_keys = case["sort_keys"].as_bool().unwrap();
        let expected = case["text"].as_str().unwrap();
        let actual = dumps(&value, sort_keys);
        if actual != expected {
            let at = actual
                .bytes()
                .zip(expected.bytes())
                .position(|(a, b)| a != b)
                .unwrap_or(actual.len().min(expected.len()));
            let from = at.saturating_sub(60);
            panic!(
                "sort_keys={sort_keys}: differs at byte {at}\n ours: {:?}\npython: {:?}",
                &actual[from..(at + 60).min(actual.len())],
                &expected[from..(at + 60).min(expected.len())]
            );
        }
    }
}

#[test]
fn png_matches_python_by_image() {
    let cases = fixture()["png"].as_array().unwrap().clone();
    assert!(cases.len() >= 6, "the fixture has its cases");
    for case in &cases {
        let width = case["width"].as_u64().unwrap() as u32;
        let height = case["height"].as_u64().unwrap() as u32;
        let pixels = base64(case["pixels"].as_str().unwrap());
        let expected = case["image_sha256"].as_str().unwrap();
        let ours = match case["kind"].as_str().unwrap() {
            "indexed" => {
                let palette: Vec<[u8; 3]> = case["palette"]
                    .as_array()
                    .unwrap()
                    .iter()
                    .map(|c| {
                        let c: Vec<u8> = c
                            .as_array()
                            .unwrap()
                            .iter()
                            .map(|v| v.as_u64().unwrap() as u8)
                            .collect();
                        [c[0], c[1], c[2]]
                    })
                    .collect();
                let transparent: Vec<u8> = case["transparent"]
                    .as_array()
                    .unwrap()
                    .iter()
                    .map(|v| v.as_u64().unwrap() as u8)
                    .collect();
                encode_indexed(width, height, &pixels, &palette, &transparent).unwrap()
            }
            "rgb" => encode_rgb(width, height, &pixels).unwrap(),
            other => panic!("unknown kind {other}"),
        };
        let python_png = base64(case["png"].as_str().unwrap());
        assert_eq!(
            image_sha256(&python_png).unwrap(),
            expected,
            "our digest of Python's file"
        );
        assert_eq!(
            image_sha256(&ours).unwrap(),
            expected,
            "our file, {width}x{height}"
        );
    }
}
